actions.script:
def fromD = fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
def thruD = thruDate ?: fromD
periodStr = "${fromD} to ${thruD}"
generatedStr = ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')
def dStart = java.sql.Timestamp.valueOf(fromD + ' 00:00:00')
def dEnd = java.sql.Timestamp.valueOf(thruD + ' 23:59:59')

// ZE-INV-IV-035 pattern: this is a standalone (fop) path outside the authz filter — scope org explicitly
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def wf = ec.entity.find("zenith.erp.pos.PosStockWastage")
    .condition("wastageDate", "greater-equals", dStart)
    .condition("wastageDate", "less-equals", dEnd)
if (_org && _org != '_NA_') wf.condition("organizationPartyId", _org)
def wastages = wf.list()

def reasonMap = new LinkedHashMap(); def productMap = new LinkedHashMap()
wastages.each { w ->
    def reason = w.wastageReason ?: 'Other'
    if (!reasonMap[reason]) {
        def ev = ec.entity.find("moqui.basic.Enumeration").condition("enumId", reason).one()
        reasonMap[reason] = [name: ev?.description ?: reason, loss: 0.0G, qty: 0.0G, n: 0]
    }
    reasonMap[reason].loss += (w.totalLoss ?: 0) as BigDecimal
    reasonMap[reason].qty += (w.quantity ?: 0) as BigDecimal
    reasonMap[reason].n++
    def pn = w.productName ?: w.productId ?: 'Unknown'
    if (!productMap[pn]) productMap[pn] = [name: pn, loss: 0.0G, qty: 0.0G, n: 0]
    productMap[pn].loss += (w.totalLoss ?: 0) as BigDecimal
    productMap[pn].qty += (w.quantity ?: 0) as BigDecimal
    productMap[pn].n++
}
def zinr = context.zinr
def fmtAmt = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00')) }
def fmtQty = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0')) }

reasons = reasonMap.values().sort { -(it.loss as BigDecimal) }.collect {
    [name: it.name, nStr: it.n.toString(), qtyStr: fmtQty(it.qty), lossStr: fmtAmt(it.loss)] }
products = productMap.values().sort { -(it.loss as BigDecimal) }.collect {
    [name: it.name, nStr: it.n.toString(), qtyStr: fmtQty(it.qty), lossStr: fmtAmt(it.loss)] }

def tLoss = reasonMap.values().sum { it.loss } ?: 0.0G
def tQty = reasonMap.values().sum { it.qty } ?: 0.0G
def tN = reasonMap.values().sum { it.n } ?: 0
totLossStr = fmtAmt(tLoss)
totLossCardStr = 'Rs. ' + fmtAmt(tLoss)
totQtyStr = fmtQty(tQty)
totNStr = tN.toString()
